BEGIN;
CREATE TABLE IF NOT EXISTS zoning_users(id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,qualification_ref TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS zoning_tenants(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS zoning_memberships(tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),user_id BIGINT NOT NULL REFERENCES zoning_users(id),role TEXT NOT NULL CHECK(role IN('matter_owner','qualified_planner','municipal_counsel','records_officer','filing_clerk','auditor','admin')),active BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS zoning_matters(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_ref TEXT NOT NULL,jurisdiction TEXT NOT NULL,as_of_date DATE NOT NULL,title TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'intake' CHECK(state IN('intake','source_review','source_conflict','analysis','exception','human_review','rejected','approved','filing_queued','filing_failed','filed','closed')),revision INTEGER NOT NULL DEFAULT 1,owner_id BIGINT NOT NULL REFERENCES zoning_users(id),retention_until TIMESTAMPTZ NOT NULL,legal_hold BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,matter_ref));
CREATE TABLE IF NOT EXISTS zoning_sources(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_id BIGINT NOT NULL REFERENCES zoning_matters(id),source_ref TEXT NOT NULL,source JSONB NOT NULL,evidence_digest CHAR(64) NOT NULL,classification TEXT NOT NULL,ingested_by BIGINT NOT NULL REFERENCES zoning_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,matter_id,source_ref),UNIQUE(tenant_id,matter_id,evidence_digest));
CREATE TABLE IF NOT EXISTS zoning_rule_resolutions(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_id BIGINT NOT NULL REFERENCES zoning_matters(id),resolution JSONB NOT NULL,rule_set_digest CHAR(64) NOT NULL,resolved_by BIGINT NOT NULL REFERENCES zoning_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,matter_id,rule_set_digest));
CREATE TABLE IF NOT EXISTS zoning_analyses(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_id BIGINT NOT NULL REFERENCES zoning_matters(id),rule_resolution_id BIGINT NOT NULL REFERENCES zoning_rule_resolutions(id),analysis JSONB NOT NULL,analysis_digest CHAR(64) NOT NULL,created_by BIGINT NOT NULL REFERENCES zoning_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,matter_id,analysis_digest));
CREATE TABLE IF NOT EXISTS zoning_deadlines(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_id BIGINT NOT NULL REFERENCES zoning_matters(id),deadline JSONB NOT NULL,deadline_digest CHAR(64) NOT NULL,created_by BIGINT NOT NULL REFERENCES zoning_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,matter_id,deadline_digest));
CREATE TABLE IF NOT EXISTS zoning_conversations(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_id BIGINT NOT NULL REFERENCES zoning_matters(id),created_by BIGINT NOT NULL REFERENCES zoning_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS zoning_copilot_messages(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),conversation_id BIGINT NOT NULL REFERENCES zoning_conversations(id),question TEXT NOT NULL,response JSONB NOT NULL,response_digest CHAR(64) NOT NULL,actor_id BIGINT NOT NULL REFERENCES zoning_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,conversation_id,response_digest));
CREATE TABLE IF NOT EXISTS zoning_approvals(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_id BIGINT NOT NULL REFERENCES zoning_matters(id),analysis_id BIGINT NOT NULL REFERENCES zoning_analyses(id),deadline_id BIGINT NOT NULL REFERENCES zoning_deadlines(id),approval JSONB NOT NULL,approval_digest CHAR(64) NOT NULL,approved_by BIGINT NOT NULL REFERENCES zoning_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,matter_id,approval_digest));
CREATE TABLE IF NOT EXISTS zoning_filing_outbox(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_id BIGINT NOT NULL REFERENCES zoning_matters(id),approval_id BIGINT NOT NULL REFERENCES zoning_approvals(id),idempotency_key TEXT NOT NULL,payload JSONB NOT NULL,payload_digest CHAR(64) NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','processing','retry','succeeded','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),external_ref TEXT,signed_receipt_digest CHAR(64),last_error_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS zoning_delivery_receipts(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_id BIGINT NOT NULL REFERENCES zoning_matters(id),provider TEXT NOT NULL,delivery JSONB NOT NULL,delivery_digest CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,matter_id,delivery_digest));
CREATE TABLE IF NOT EXISTS zoning_provider_failures(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_id BIGINT REFERENCES zoning_matters(id),provider TEXT NOT NULL,operation TEXT NOT NULL,error_code TEXT NOT NULL,retryable BOOLEAN NOT NULL,sanitized_detail TEXT NOT NULL DEFAULT 'provider detail redacted',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS zoning_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES zoning_tenants(id),matter_id BIGINT REFERENCES zoning_matters(id),actor_id BIGINT REFERENCES zoning_users(id),event_type TEXT NOT NULL,payload JSONB NOT NULL,evidence_digest CHAR(64),occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS zoning_filing_ready_idx ON zoning_filing_outbox(status,next_attempt_at);CREATE INDEX IF NOT EXISTS zoning_matter_state_idx ON zoning_matters(tenant_id,state,updated_at);
CREATE OR REPLACE FUNCTION prevent_zoning_evidence_mutation() RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'zoning evidence is append-only';END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION guard_zoning_filing_request() RETURNS trigger AS $$BEGIN IF OLD.tenant_id<>NEW.tenant_id OR OLD.matter_id<>NEW.matter_id OR OLD.approval_id<>NEW.approval_id OR OLD.idempotency_key<>NEW.idempotency_key OR OLD.payload IS DISTINCT FROM NEW.payload OR OLD.payload_digest<>NEW.payload_digest OR OLD.created_at<>NEW.created_at THEN RAISE EXCEPTION 'filing request evidence is immutable';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION guard_zoning_hold() RETURNS trigger AS $$BEGIN IF OLD.legal_hold=TRUE AND NEW.legal_hold=FALSE THEN RAISE EXCEPTION 'legal hold requires a separate authorized release record';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
DO $$DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['zoning_sources','zoning_rule_resolutions','zoning_analyses','zoning_deadlines','zoning_copilot_messages','zoning_approvals','zoning_delivery_receipts','zoning_audit_events'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_append_only ON %I',t,t);EXECUTE format('CREATE TRIGGER %I_append_only BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_zoning_evidence_mutation()',t,t);END LOOP;END$$;
DROP TRIGGER IF EXISTS zoning_filing_request_guard ON zoning_filing_outbox;CREATE TRIGGER zoning_filing_request_guard BEFORE UPDATE ON zoning_filing_outbox FOR EACH ROW EXECUTE FUNCTION guard_zoning_filing_request();
DROP TRIGGER IF EXISTS zoning_hold_guard ON zoning_matters;CREATE TRIGGER zoning_hold_guard BEFORE UPDATE ON zoning_matters FOR EACH ROW EXECUTE FUNCTION guard_zoning_hold();
COMMIT;
